function authorizeTicketEdit(user, ticket) {
  if (ticket === null) return 'not-found';

  const isOwner = ticket.ownerId === user.id;
  const isAdmin = user.role === 'admin';
  if (!isOwner && !isAdmin) return 'not-found';

  if (ticket.status === 'closed') return 'forbidden';
  return 'allow';
}

